insert into public.p1_knowledgebase (kb_id, topic, guidance) values
('KB-01', 'Settlement timeline', 'Standard settlements are credited T+2 business days after payment capture. Weekends and bank holidays are excluded. Merchants can see settlement status on Dashboard > Settlements.'),
('KB-02', 'Delayed settlement (bank-side)', 'Settlements can be delayed by up to 2 additional business days due to bank-side processing. If status is ''Delayed'', share the expected settlement date from the system. Do not promise a date that is not shown in the system.'),
('KB-03', 'Settlement holds: risk review and chargeback reserve', 'A ''Risk review'' hold can last up to 5 business days from the hold date. A ''Chargeback reserve'' hold stays until the related dispute is closed. Customer Success cannot release or shorten holds and must escalate to Risk Ops. Do not share internal risk reasons with the merchant.'),
('KB-04', 'Settlement hold: KYC pending', 'Settlements are held while KYC is pending. They are released within 1 business day of KYC being verified. Guide the merchant to complete pending documents in Dashboard > Account > KYC.'),
('KB-05', 'Settlement hold: bank account mismatch', 'The name on the bank account must match the registered business or PAN name. Merchants can re-add the account in Dashboard > Settings > Bank Account. Re-verification (penny-drop) completes within 24 hours.'),
('KB-06', 'Payment failures', 'Common causes: bank declines, insufficient funds, UPI app time-outs, wrong card details. Advise the customer to retry or use another method. If money is deducted but the order failed, it is auto-reversed in 5-7 business days. If the merchant''s 7-day payment success rate is below 85%, treat it as a possible degradation and escalate to Payments Ops; do not blame the customer.'),
('KB-07', 'Refunds', 'Refunds are credited to the original payment source in 5-7 business days. An ARN is available after 3 days. Refunds of Rs 1,00,000 or more are manually approved by Refund Ops; Customer Success must escalate them and must not promise a timeline.'),
('KB-08', 'Chargebacks', 'When a customer disputes a payment, the merchant gets a notice on the Dashboard under Disputes. The merchant must upload evidence (invoice, proof of delivery, communication) within 7 calendar days. A missed deadline means the dispute is lost automatically. Disputes cannot be blocked in advance.'),
('KB-09', 'Fees and invoices', 'GST invoices for fees are generated by the 5th of every month under Dashboard > Reports > Invoices. Pricing (MDR) changes, waivers and refunds of fee differences are handled only by the Account Manager. Customer Success cannot negotiate or promise them.'),
('KB-10', 'KYC documents', 'Required: PAN of business/owner, address proof, bank account proof, GST certificate (if GST-registered) and ID of the authorised signatory. Re-verification can be triggered after 24 months or when details change. Genuine re-verification requests only come from the Dashboard or @example.com emails.'),
('KB-11', 'Changing account details', 'Email and mobile can be changed in Settings using OTP verification. A change of legal entity name or business type requires a fresh application and cannot be done by edit.'),
('KB-12', 'API: common errors', 'SIGNATURE_MISMATCH: verify the signature using the key secret on ''order_id|payment_id''. BAD_REQUEST_ERROR ''order amount mismatch'': amounts must be sent in paise (Rs 499 = 49900).'),
('KB-13', 'Webhooks', 'If webhooks are not received: check the URL is publicly reachable, returns HTTP 200 within 5 seconds, and the event is subscribed. Failed webhooks are retried for up to 24 hours.'),
('KB-14', 'Test vs live keys', '''Authentication failed'' on a live site usually means test keys are being used in production. Use live key ID and secret generated after activation.'),
('KB-15', 'Escalation policy', 'Legal threats, allegations of fraud or bribery by staff, media threats, data-security claims, regulator complaints and suspected account takeover must be escalated immediately to the right team. Do not argue, admit fault, or give commitments in the reply.'),
('KB-16', 'Tone and promises', 'Be empathetic and brief. Never promise a date, refund, waiver or release that is not shown in the system. If the merchant ID or payment ID is missing, ask for it before anything else. Reply in the merchant''s language style (English or Hinglish).'),
('KB-17', 'Account closure', 'Closure is processed only after all pending settlements, refunds and disputes are cleared. Requests go through the Account Manager and Risk Ops.');
